insert into media_draft (
    project_id, content_type, title_options, cover_text, body, image_page_plan, shot_list,
    subtitles, hashtags, version, status, created_by, created_at, updated_at
) values (
    #{projectId}, #{contentType}, #{titleOptions}, #{coverText}, #{body}, #{imagePagePlan}, #{shotList},
    #{subtitles}, #{hashtags}, #{version}, #{status}, #{createdBy}, #{createdAt}, #{updatedAt}
)
